using System;using UnityEngine;
namespace SoulboundLegends.NetworkTransport;
public sealed class NetworkTransportManager:MonoBehaviour{public NetworkTransportConfig config;[SerializeField] string authenticationToken;[SerializeField] string reconnectToken;[SerializeField] bool autoConnect;INetworkTransportProvider provider;public ConnectionState State=>provider?.State??ConnectionState.Disconnected;public NetworkStats Stats=>provider?.Stats??default;public event Action<NetworkMessage> MessageReceived;public event Action<ulong> Connected;public event Action<ulong,string> Disconnected;void Awake(){DontDestroyOnLoad(gameObject);provider=new UdpReliableTransportProvider(config?config.maxPacketBytes:1200,config?config.enableHmac:true,config?config.deploymentSharedSecret:"");provider.MessageReceived+=m=>MessageReceived?.Invoke(m);provider.Connected+=id=>Connected?.Invoke(id);provider.Disconnected+=(id,r)=>Disconnected?.Invoke(id,r);if(autoConnect)Connect();}public void Connect(){if(config==null)throw new InvalidOperationException("NetworkTransportConfig is required");provider.StartClient(new NetworkEndpoint(config.serverAddress,config.serverPort),authenticationToken,reconnectToken);}public void Send(TransportChannel c,NetworkMessageType t,byte[] payload)=>provider?.Send(1,c,t,payload);void Update(){provider?.Tick(Time.unscaledDeltaTime);}void OnDestroy(){provider?.Dispose();}}
